        case .emailFilter: return false
        case .calendarWindow: return false
        case .topicMonitor: return false
        case .connectorEvent: return false
        case .folderChange: return true
        case .manual: return false
        }
    }
}

/// What happens to occurrences that came due while nothing could run them.
public enum JunoWorkMissedRunPolicy: String, CaseIterable, Codable, Sendable {
    /// Forget them and wait for the next occurrence.
    case skip = "skip"
    /// Catch up with a single run, however many were missed.
    case runOnce = "run_once"
    /// Run every missed occurrence in order.
    case runAll = "run_all"
}

/// The security-relevant facts Work records whether or not anyone is watching.
public enum JunoWorkAuditKind: String, CaseIterable, Codable, Sendable {
    /// A user handed a run access to something.
    case grantCreated = "grant_created"
    /// That access was taken away.
    case grantRevoked = "grant_revoked"
    /// A Mac was switched on for Juno Work.
    case hostEnabled = "host_enabled"
    /// A Mac was switched off, reversibly.
    case hostDisabled = "host_disabled"
    /// A Mac's credentials were revoked, so it cannot come back without being paired again.
    case hostRevoked = "host_revoked"
    /// A host took the lease on a relayed command.
    case commandClaimed = "command_claimed"
    /// A host declined a command it was not entitled to run.
    case commandRefused = "command_refused"
    /// Permission to act was asked for.
    case approvalRequested = "approval_requested"
    /// A user allowed or refused it.
    case approvalDecided = "approval_decided"
    /// An approval was presented a second time and rejected, so one yes cannot authorise two actions.
    case approvalReplayRefused = "approval_replay_refused"
    /// A layer reduced what the run may do; recorded so the effective policy can be explained.
    case policyNarrowed = "policy_narrowed"
    /// An attempt to send data somewhere it was not allowed to go.
    case egressBlocked = "egress_blocked"
    /// Content the run read tried to instruct it, and was treated as data.
    case injectionDetected = "injection_detected"
    /// A file operation tried to leave the granted folder.
    case pathEscapeRefused = "path_escape_refused"
    /// An erase was proposed, which no access mode ever permits on its own.
    case permanentDeleteRequested = "permanent_delete_requested"
    /// A picture of the user's screen was taken, and where it went.
    case screenshotCaptured = "screenshot_captured"
    /// A skill version was loaded into a run.
    case skillApplied = "skill_applied"
    /// A less precise tool was refused while a more precise one could serve the same intent.
    case tierDowngradeRefused = "tier_downgrade_refused"
}

/// How much an audit entry matters.
public enum JunoWorkAuditSeverity: String, CaseIterable, Codable, Sendable {
    /// It happened and it was meant to.
    case info = "info"
    /// It happened and someone should know.
    case warning = "warning"
    /// Juno declined to do something.
    case refusal = "refusal"
    /// A rule was broken, or an attempt was made to break one.
    case violation = "violation"
}

/// Which piece of Juno did the thing being recorded.
public enum JunoWorkActor: String, CaseIterable, Codable, Sendable {
    /// The web application.
    case web = "web"
    /// The Mac app, which is also the local host.
    case macos = "macos"
    /// The iPhone and iPad app.
    case ios = "ios"
    /// Juno's own executor.
    case cloudRunner = "cloud_runner"
    /// The unattended trigger loop.
    case scheduler = "scheduler"
}

/// How closely content must be held, lowest first. Sensitivity only ever rises as a run reads more.
public enum JunoWorkSensitivity: String, CaseIterable, Codable, Sendable, Comparable {
    /// Already published, or intended to be.
    case `public` = "public"
    /// The user's own material, not meant for anyone else.
    case `internal` = "internal"
    /// Someone else's material the user is trusted with.
    case confidential = "confidential"
    /// Credentials, health, financial or legal material. Never leaves the Mac in a picture.
    case restricted = "restricted"

    /// Whether a screenshot containing this may leave the Mac. Checked before the image is stored or relayed; a redaction pass over an image already on the phone has redacted nothing.
    public var allowsScreenshotRelay: Bool {
        switch self {
        case .`public`: return true
        case .`internal`: return true
        case .confidential: return true
        case .restricted: return false
        }
    }

    /// Ordering follows the contract's own order, so a comparison between two
    /// of these is answered the same way on both platforms.
    private var rank: Int {
        JunoWorkSensitivity.allCases.firstIndex(of: self) ?? 0
    }

    public static func < (lhs: JunoWorkSensitivity, rhs: JunoWorkSensitivity) -> Bool {
        lhs.rank < rhs.rank
    }
}
